// Merge do payload do webhook (mensagem original) + GET /conversations/:id (full)
const webhook = $('webhook_chatwoot1').first().json || {};
const full = $input.first().json || {};
const body = webhook.body || {};
const msgData = body.data || {};

// GET_Conversation_Full retorna { data: { ...conversation } }
const conv = (full && full.data) ? full.data : {};

const att0 = (msgData.attachments && msgData.attachments[0]) || null;
const apiUrl = $('config1').first().json.gleps_api_url;

return [{
  json: {
    body: body,

    // Campos da mensagem atual (webhook)
    type_message: msgData.contentType || 'text',
    content_message: msgData.content || '',
    message: msgData.content || '',
    messageType: (att0 && att0.fileType) || msgData.contentType || 'text',
    isAudio: !!(att0 && att0.fileType === 'audio'),
    // FIX-AUDIO: download SEMPRE pela rota de integracao (API key) — o
    // fileUrl inbound do WhatsApp e CDN criptografado (.enc), inutil direto.
    audio_download_url: (att0 && att0.id) ? (apiUrl + '/attachments/' + att0.id) : '',
    audioUrl: (att0 && att0.fileUrl) || '',

    // Dados do contato/conversa
    name: (msgData.contact && msgData.contact.nome) || (conv.contact && conv.contact.nome) || '',
    // FIX-SESSAO: msgData.externalId é o ID DA MENSAGEM (3EB0...), não o JID —
    // usá-lo criava sessão nova a cada msg (quebrava debounce + memória).
    // O JID real é o externalId da CONVERSA; fallback: telefone do contato.
    remotejid: conv.externalId || msgData.contact && msgData.contact.remoteJid || '',
    clean_number: (msgData.contact && msgData.contact.telefone) || (conv.contact && conv.contact.telefone) || '',
    conversation_id: msgData.conversationId || conv.id || null,
    account_id: body.accountId || conv.accountId || null,

    // Circuit breaker inputs (do GET full)
    _custom_attributes: conv.customAttributes || {},
    _additional_attributes: conv.additionalAttributes || {},
    _assignee_id: conv.assigneeId || null,
    _status: conv.status || null,
    // FIX-LABELS: no Gleps o label vem em l.tag.name (ConversationLabel -> Tag)
    _labels: Array.isArray(conv.labels)
      ? conv.labels.map(l => (typeof l === 'string' ? l : ((l.tag && (l.tag.name || l.tag.slug)) || l.name || l.label || '')))
      : []
  }
}];

// Pega todos os itens que chegam do nó Postgres
const allItems = $items();

// Retorna um ÚNICO item novo.
// Este item contém uma propriedade 'history_items' que é um array
// com os dados de todos os itens originais.
return [{
  json: {
    history_items: allItems.map(item => item.json)
  }
}];

// Formata as mensagens de forma resiliente e segura para o Postgres
const historyItems = $json.history_items;

if (!Array.isArray(historyItems) || historyItems.length === 0) {
  return [{ json: { history: '', email_capturado: '' } }];
}

const safeString = (value) => {
  if (value === null || value === undefined) return '';
  if (typeof value === 'string') return value;
  try {
    return JSON.stringify(value);
  } catch {
    return String(value);
  }
};

const extractContent = (value) => {
  if (value === null || value === undefined) return '';
  let content = value;

  if (typeof value !== 'string') {
    content = safeString(value);
  } else {
    try {
      const parsed = JSON.parse(value);
      if (parsed?.output) {
        content = parsed.output.mensagem_de_resposta || parsed.output.message || safeString(parsed.output);
      } else if (parsed?.content) {
        content = safeString(parsed.content);
      }
    } catch {
      // Texto puro
    }
  }

  // Anti-bola de neve: remove marcador de histórico duplicado
  if (typeof content === 'string' && content.includes('Histórico recente:')) {
    content = content.split('Histórico recente:')[0].trim();
  }

  return content;
};

const formattedHistory = historyItems
  .map((item) => {
    if (!item) return null;
    let role = '';
    let content = '';

    if (item.message) {
      let parsedMessage = item.message;
      if (typeof parsedMessage === 'string') {
        try { parsedMessage = JSON.parse(parsedMessage); } catch { parsedMessage = null; }
      }
      if (parsedMessage?.type) {
        role = parsedMessage.type === 'ai' ? 'IA' : 'Humano';
        content = extractContent(parsedMessage.content);
      }
    } else if (item.type) {
      role = item.type === 'ai' ? 'IA' : 'Humano';
      content = extractContent(item.content);
    }

    if (role && content) {
      const cleanContent = content.toString().replace(/\\/g, '\\\\').replace(/\n+/g, ' ');
      return `${role}: ${cleanContent}`;
    }

    return null;
  })
  .filter(Boolean)
  .join('\n');

const _msgAtual = $('Mensagem_Final+variaveis').first().json.msg || '';
const _textosLead = [_msgAtual];
(historyItems || []).forEach((it) => {
  let pm = it && it.message;
  if (typeof pm === 'string') { try { pm = JSON.parse(pm); } catch { pm = null; } }
  if (pm && pm.type && pm.type !== 'ai') {
    _textosLead.push(typeof pm.content === 'string' ? pm.content : JSON.stringify(pm.content || ''));
  }
});
const _m = _textosLead.join(' ').match(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/);
const email_capturado = _m ? _m[0].toLowerCase() : '';

return [{
  json: {
    history: formattedHistory,
    email_capturado: email_capturado
  }
}];

