function cleanText(text) {
  if (!text) return '';

  return String(text)
    // normaliza tracos
    .replace(/[–—]/g, '-')
    // normaliza aspas
    .replace(/[‘’]/g, "'")
    .replace(/[“”]/g, '"')
    // remove caracteres de controle invisiveis (escapado \u para nao corromper o JSON do fluxo)
    .replace(/[\u0000-\u001f]/g, '')
    // quebra de linha ok, mas vamos padronizar
    .replace(/\n+/g, ' ')
    .trim();
}

// corrige "palavra.Palavra" -> "palavra. Palavra" (fim de frase + maiuscula)
function fixSentenceSpacing(text) {
  if (!text) return '';
  return String(text)
    .replace(/([.!?])([A-ZÀ-Ý])/g, '$1 $2')
    .replace(/\s{2,}/g, ' ')
    .trim();
}

// extrai o primeiro e-mail de um texto (vazio se nao houver)
function extrairEmail(text) {
  if (!text) return '';
  const m = String(text).match(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/);
  return m ? m[0].toLowerCase() : '';
}

return items.map(item => {
  const o = item.json.output || item.json || {};

  const transferir =
    o.transferir_para_humano === true ||
    o.transferir_para_humano === 'true';

  const resolver_raw =
    o.resolver_conversa === true ||
    o.resolver_conversa === 'true';

  let resolver = transferir ? false : resolver_raw;
  let etapa = cleanText(o.etapa_final || o.etapa || 'novo-lead');
  let mensagem = fixSentenceSpacing(cleanText(o.mensagem_de_resposta || ''));

  // GUARD E1 (anti e-mail inventado): usa o email_capturado do histórico
  const emailCapturado = extrairEmail($('retorna histórico formatado').first().json.email_capturado || '');
  const confirmouAgendamento = etapa === 'agendado' && resolver_raw === true;
  const emailNaMensagem = extrairEmail(mensagem);
  const semEmailReal = !emailCapturado;
  const emailNaoBate = emailNaMensagem && emailCapturado && emailNaMensagem !== emailCapturado;
  if (confirmouAgendamento && (semEmailReal || emailNaoBate)) {
    // bloqueia a confirmacao fake e devolve a vez pro agente coletar o e-mail
    mensagem = 'Show! Pra fechar o agendamento certinho, me confirma teu melhor e-mail?';
    resolver = false;
    etapa = 'agendado';
  }

  return {
    json: {
      etapa: etapa,
      mensagem_original: cleanText(o.mensagem_original || ''),
      mensagem_de_resposta: mensagem,
      transferir_para_humano: transferir,
      resolver_conversa: resolver
    }
  };
});

// Gleps GET /api/integrations/users retorna {data:[{id,nome,email,status,lastSeenAt}]}.
const first = $input.first()?.json || {};
let agents = [];
if (Array.isArray(first.data)) {
  agents = first.data;
} else {
  agents = $input.all().map(i => i.json);
}

// Filtro: só online (Gleps AgentAvailability.status)
const onlineAgents = agents.filter(a => (a.status === 'online' || a.availability_status === 'online' || a.available === true));

if (onlineAgents.length === 0) {
  return [{ json: { has_agent: false, assignee_id: null, assignee_name: null } }];
}

const chosen = onlineAgents.length === 1
  ? onlineAgents[0]
  : onlineAgents[Math.floor(Math.random() * onlineAgents.length)];

return [{
  json: {
    has_agent: true,
    assignee_id: chosen.id,
    assignee_name: chosen.nome || chosen.name || chosen.email
  }
}];
